      const rollOut = solveAxis('roll', tauRollMix);
      const pitchOut = solveAxis('pitch', tauPitchMix);
      const yawRateOut = clamp(rates.yaw + tauYawMix / (8 * inertia), -2, 2);

      const action = {
        thrust: clamp(thrustOut, 0, 1),
        roll: rollOut,
        pitch: pitchOut,
        yawRate: yawRateOut,
      };
      lastAction = action;
      return action;
    },
  };
}

