          { t: 5.25, p: { x: GATES[2].x, y: GATES[2].y, z: GATES[2].z }, v: { x: 0.85, y: 0, z: 0 }, a: { x: 0, y: 0, z: 0 } },
          { t: 7.00, p: { x: PAD.x, y: 0.075, z: PAD.z }, v: { x: 0, y: 0, z: 0 }, a: { x: 0, y: 0, z: 0 } },
        ];
      } else if (lastAction) {
        const dtSub = TASK.dt / TASK.substeps;
        for (let s = 0; s < TASK.substeps; s++) stepShadow(shadow, lastAction, params, dtSub);
      }

      const t = shadow.t;
      const pos = shadow.pos, vel = shadow.vel, att = shadow.att, rates = shadow.rates;

      let refP = { x: PAD.x, y: 0.07, z: PAD.z };
      let refV = { x: 0, y: 0, z: 0 };
      let refA = { x: 0, y: 0, z: 0 };
      let refJ = { x: 0, y: 0, z: 0 };

