        const desiredTorquePitch = -TASK.inertia * (params.mass / TASK.baseMass) * (80 * att.pitch + 16 * rates.pitch);
        const inertia = TASK.inertia * params.mass / TASK.baseMass;
        const dtSub = 0.005;
        const errRoll = (desiredTorqueRoll / inertia + 13 * rates.roll - 22 * shadow.integral.roll) / (65 + 22 * dtSub);
        const errPitch = (desiredTorquePitch / inertia + 13 * rates.pitch - 22 * shadow.integral.pitch) / (65 + 22 * dtSub);
        const act = {
          thrust: 0,
          roll: clamp(att.roll + errRoll, -0.15, 0.15),
          pitch: clamp(att.pitch + errPitch, -0.15, 0.15),
          yawRate: clamp(rates.yaw - 2.0 * att.yaw, -2, 2),
        };
        lastAction = act;
        return act;
      }

      const kp = 14.0, kd = 7.2;
      const kpY = 16.0, kdY = 8.0;
      const axDes = refA.x + kp * (refP.x - pos.x) + kd * (refV.x - vel.x);
      const ayDes = refA.y + kpY * (refP.y - pos.y) + kdY * (refV.y - vel.y);
      const azDes = refA.z + kp * (refP.z - pos.z) + kd * (refV.z - vel.z);

      const m = params.mass, cd = TASK.linearDrag;
      const Fx = m * axDes - cd * (wPrev.x - vel.x);
      const Fy = Math.max(0.5, m * (ayDes + TASK.gravity) - cd * (wPrev.y - vel.y));
      const Fz = m * azDes - cd * (wPrev.z - vel.z);

      const jxDes = refJ.x - (cd / m) * (wDot.x - axDes);
      const jzDes = refJ.z - (cd / m) * (wDot.z - azDes);

