      const pitchRateDes = clamp((cy * jxDes - sy * jzDes) / TASK.gravity, -3.0, 3.0);
      const rollRateDes = clamp(-(sy * jxDes + cy * jzDes) / TASK.gravity, -3.0, 3.0);

      const cosTilt = Math.max(0.5, Math.cos(att.roll) * Math.cos(att.pitch));
      const sumDes = Fy / cosTilt;
      const sumCurr = shadow.motors[0] + shadow.motors[1] + shadow.motors[2] + shadow.motors[3];
      const sumCmd = clamp(sumDes + 0.35 * (sumDes - sumCurr), 0.2, 15.5);

      const inertia = TASK.inertia * params.mass / TASK.baseMass;
      const mRollCurr = shadow.motors[0] * MOTOR_Z[0] + shadow.motors[1] * MOTOR_Z[1] + shadow.motors[2] * MOTOR_Z[2] + shadow.motors[3] * MOTOR_Z[3];
      const mPitchCurr = -(shadow.motors[0] * MOTOR_X[0] + shadow.motors[1] * MOTOR_X[1] + shadow.motors[2] * MOTOR_X[2] + shadow.motors[3] * MOTOR_X[3]);
      const alphaRollCurr = TASK.arm * mRollCurr / inertia - 0.4 * rates.roll;
      const alphaPitchCurr = TASK.arm * mPitchCurr / inertia - 0.4 * rates.pitch;

      const wn = 28.0, zeta = 0.9, ka = 0.45 * params.lag * wn * wn;
      const alphaRollCmd = wn * wn * (rollDes - att.roll) + 2 * zeta * wn * (rollRateDes - rates.roll) - ka * alphaRollCurr;
      const alphaPitchCmd = wn * wn * (pitchDes - att.pitch) + 2 * zeta * wn * (pitchRateDes - rates.pitch) - ka * alphaPitchCurr;

      const tauRollCmd = inertia * (alphaRollCmd + 0.4 * rates.roll);
      const tauPitchCmd = inertia * (alphaPitchCmd + 0.4 * rates.pitch);
      const tauYawCmd = inertia * (-12.0 * att.yaw - 6.0 * rates.yaw);

      const d = [0, 0, 0, 0];
      for (let i = 0; i < 4; i++) {
        const fi = 0.25 * sumCmd +
          tauRollCmd * MOTOR_Z[i] / (4 * TASK.arm) -
          tauPitchCmd * MOTOR_X[i] / (4 * TASK.arm) +
          tauYawCmd * SPIN[i] / (4 * TASK.yawCoefficient);
        const w = (i === params.weakMotor) ? (1 - params.weakness) : 1;
        d[i] = clamp(fi / w, 0, TASK.maxMotorThrust);
      }

      const thrustOut = (d[0] + d[1] + d[2] + d[3]) / (4 * TASK.maxMotorThrust);
      const tauRollMix = TASK.arm * (d[0] * MOTOR_Z[0] + d[1] * MOTOR_Z[1] + d[2] * MOTOR_Z[2] + d[3] * MOTOR_Z[3]);
      const tauPitchMix = -TASK.arm * (d[0] * MOTOR_X[0] + d[1] * MOTOR_X[1] + d[2] * MOTOR_X[2] + d[3] * MOTOR_X[3]);
      const tauYawMix = TASK.yawCoefficient * (d[0] * SPIN[0] + d[1] * SPIN[1] + d[2] * SPIN[2] + d[3] * SPIN[3]);

      const dtSub = TASK.dt / TASK.substeps;
      const solveAxis = (axis, tauMix) => {
        const target = tauMix / inertia;
        let err = (target + 13 * rates[axis] - 22 * shadow.integral[axis]) / (65 + 22 * dtSub);
        const nextInt = shadow.integral[axis] + err * dtSub;
        if (nextInt > 0.35 || nextInt < -0.35) {
          const clampedInt = clamp(nextInt, -0.35, 0.35);
          err = (target + 13 * rates[axis] - 22 * clampedInt) / 65;
        }
        return clamp(att[axis] + err, -0.6, 0.6);
      };

      const rollOut = solveAxis('roll', tauRollMix);
      const pitchOut = solveAxis('pitch', tauPitchMix);
      const yawRateOut = clamp(rates.yaw + tauYawMix / (8 * inertia), -2, 2);

      const action = {
        thrust: clamp(thrustOut, 0, 1),
        roll: rollOut,
        pitch: pitchOut,
        yawRate: yawRateOut,
      };
      lastAction = action;
      return action;
    },
  };
}
